public class MaxXor {

    static class BNode {
        BNode[] c = new BNode[2];
    }

    public static int maxXor(int[] a) {
        if (a.length == 0) {
            return 0;
        }
        BNode root = new BNode();
        for (int x : a) {
            BNode n = root;
            for (int b = 30; b >= 0; b--) {
                int bit = x >> b & 1;
                if (n.c[bit] == null) {
                    n.c[bit] = new BNode();
                }
                n = n.c[bit];
            }
        }
        int best = 0;
        for (int x : a) {
            BNode n = root;
            int cur = 0;
            for (int b = 30; b >= 0; b--) {
                int want = (x >> b & 1) ^ 1; // a 1 in a HIGH bit beats all lower bits together
                if (n.c[want] != null) {
                    cur |= 1 << b;
                    n = n.c[want];
                } else {
                    n = n.c[want ^ 1];
                }
            }
            best = Math.max(best, cur);
        }
        return best;
    }
}

