// Grader test class (do not edit): one command per input line; after each command it prints the result and the
// state read from the REAL links of your structure (Kiem follows the fields node by node).
public class KiemTra {
    static String[] p;

    static int n(int i) {
        return Integer.parseInt(p[i]);
    }

    static int[] arr(String s) {
        if (s.equals("-")) {
            return new int[0];
        }
        String[] t = s.split(",");
        int[] a = new int[t.length];
        for (int i = 0; i < t.length; i++) {
            a[i] = Integer.parseInt(t[i].trim());
        }
        return a;
    }

    static String str(int[] a) {
        return Arrays.toString(a);
    }

    static String ketQua(String label, int n, String sai) {
        return sai == null ? label + ": all " + n + " agree with the brute force" : label + ": MISMATCH " + sai;
    }

    static int[] brute(int[] a) {
        int[] r = new int[a.length];
        for (int i = 0; i < a.length; i++) {
            for (int jj = i + 1; jj < a.length; jj++) {
                if (a[jj] < a[i]) {
                    r[i]++;
                }
            }
        }
        return r;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }
            p = line.split("\\s+");
            String r = "ok";
            try {
                if (p[0].equals("RUN")) {
                    r = str(CountSmaller.countSmaller(arr(p[1])));
                } else if (p[0].equals("RANDOM")) {
                    Random rnd = new Random(105);
                    String sai = null;
                    for (int t = 0; t < 3000 && sai == null; t++) {
                        int[] a = new int[rnd.nextInt(12)];
                        for (int i = 0; i < a.length; i++) {
                            a[i] = t % 3 == 0 ? rnd.nextInt() : rnd.nextInt(9) - 4;
                        }
                        String got = str(CountSmaller.countSmaller(a.clone())), want = str(brute(a));
                        if (!got.equals(want)) {
                            sai = str(a) + " -> " + got + ", expected " + want;
                        }
                    }
                    r = ketQua("3000 random arrays (duplicates, any int)", 3000, sai);
                } else {
                    final int[] a = new int[200000];
                    Random rnd = new Random(107);
                    for (int i = 0; i < a.length; i++) {
                        a[i] = rnd.nextInt();
                    }
                    final long[] s = new long[1];
                    r = Kiem.hen("200,000 numbers", 3000, new Runnable() {
                        public void run() {
                            for (int x : CountSmaller.countSmaller(a)) {
                                s[0] += x;
                            }
                        }
                    }) + ", total " + s[0];
                }
            } catch (RuntimeException e) {
                r = "THROWS " + Kiem.ten(e);
            }
            System.out.println(line + " -> " + r);
        }
    }
}

